#!/usr/bin/env bash

# Upload the documentation tarballs in the "docs" directory (as
# generated by mkDocs.sh) to Hackage.
#
# USAGE: ./uploadDocs.sh [--publish]
#
# By default the documentation is uploaded for the package
# candidates. Pass --publish to upload the documentation for the
# published packages instead. Each documentation tarball is deleted
# once it has been successfully uploaded, so re-running the script
# after a failure only retries the remaining ones.
#
# Set HACKAGE_TOKEN to authenticate with a Hackage token, otherwise
# the credentials in the cabal configuration are used.

set -uo pipefail

BINDINGS_DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )" >/dev/null 2>&1 && pwd )"
DOCS_DIR="$BINDINGS_DIR/docs"

UPLOAD_FLAGS=(--documentation)
case "${1:-}" in
    --publish)
        UPLOAD_FLAGS+=(--publish)
        ;;
    "")
        ;;
    *)
        echo "USAGE: $0 [--publish]" >&2
        exit 1
        ;;
esac

if [ -n "${HACKAGE_TOKEN:-}" ]; then
    UPLOAD_FLAGS+=(--token="$HACKAGE_TOKEN")
fi

shopt -s nullglob
DOCS=("$DOCS_DIR"/*-docs.tar.gz)

if [ ${#DOCS[@]} -eq 0 ]; then
    echo "Error: no documentation tarballs found in $DOCS_DIR, run mkDocs.sh first." >&2
    exit 1
fi

# Hackage sometimes answers with a 502 (Bad Gateway) error, which
# usually goes away when retrying. The first retry waits for 2
# seconds, and any further ones for 5 seconds, up to MAX_RETRIES.
MAX_RETRIES=10

for doc in "${DOCS[@]}"; do
    echo -n "Uploading $(basename "$doc")... "
    retries=0
    while true; do
        if result=$(cabal upload "${UPLOAD_FLAGS[@]}" "$doc" 2>&1); then
            echo "OK"
            rm "$doc"
            break
        # cabal reports the error as "... http code\n502", possibly
        # with the line break in a different place, so join the lines
        # before matching.
        elif echo "$result" | tr '\n' ' ' | grep -qE 'http code +502( |$)' \
                && [ $retries -lt $MAX_RETRIES ]; then
            if [ $retries -eq 0 ]; then
                delay=2
            else
                delay=5
            fi
            retries=$((retries + 1))
            echo -n "502 from server, retrying in ${delay}s... "
            sleep $delay
        else
            echo "FAILED"
            echo "$result" >&2
            exit 1
        fi
    done
done
